// src/components/Footer.js
import React from "react";
import "./Footer.css";

const Footer = () => {
  return (
    <footer className="footer">
      <div className="branding">
        <div>Branding stuff</div>
        <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit. Nunc maximus, nulla ut commodo</p>
      </div>
      <div className="logo">
        <img src="/logo.jpg" alt="Видавництво Старого Лева" /> 
      </div>
        <div className="social-icons">
        <a href="#facebook">FB</a>
        <a href="#twitter">TW</a>
        <a href="#linkedin">LN</a>
        <a href="#google">G+</a>
      </div>
      <div className="copyright">
        <p>2020 IoT © Copyright all rights reserved, bla bla</p>
      </div>
    </footer>
  );
};

export default Footer;
